import { DatabaseSync } from 'node:sqlite';

const db = new DatabaseSync('clinica.db');

// DDL (estrutura) roda no exec, como o CREATE TABLE
db.exec(`CREATE TABLE IF NOT EXISTS consultas (
  id INTEGER PRIMARY KEY,
  paciente_id INTEGER NOT NULL,
  dia TEXT NOT NULL,
  hora TEXT NOT NULL
)`);

// cria o índice: uma vez só, na primeira execução
db.exec(`CREATE INDEX IF NOT EXISTS idx_consultas_paciente
         ON consultas(paciente_id)`);

// as consultas continuam IGUAIS — o índice trabalha por trás
const porPaciente = db.prepare('SELECT * FROM consultas WHERE paciente_id = ?');
console.log(porPaciente.all(7));

// conferindo o plano: SEARCH ... USING INDEX = o índice está em uso
const plano = db.prepare(
  'EXPLAIN QUERY PLAN SELECT * FROM consultas WHERE paciente_id = ?',
);
console.log(plano.all(7).map((linha) => linha.detail));

import { DatabaseSync } from 'node:sqlite';

const db = new DatabaseSync('clinica.db');

db.exec(`CREATE TABLE IF NOT EXISTS medicos (
  id INTEGER PRIMARY KEY,
  nome TEXT NOT NULL,
  email TEXT NOT NULL,
  especialidade TEXT NOT NULL
)`);

db.exec(`CREATE TABLE IF NOT EXISTS consultas (
  id INTEGER PRIMARY KEY,
  medico_id INTEGER NOT NULL,
  paciente_id INTEGER NOT NULL,
  dia TEXT NOT NULL,
  hora TEXT NOT NULL
)`);

// Índice 1: o WHERE mais frequente da clínica é por paciente_id.
// Sem ele, cada tela de "consultas do paciente" varre 500 mil linhas.
db.exec(`CREATE INDEX IF NOT EXISTS idx_consultas_paciente
         ON consultas(paciente_id)`);

// Índice 2: e-mail precisa ser único (dois médicos com o mesmo e-mail
// seria um bug), então o índice UNIQUE resolve os DOIS problemas:
// acelera a busca do login E bloqueia o duplicado na escrita.
db.exec(`CREATE UNIQUE INDEX IF NOT EXISTS idx_medicos_email
         ON medicos(email)`);

// Consulta de sempre — o SQL não mudou, só a velocidade
const consultasDoPaciente = db.prepare(
  'SELECT dia, hora FROM consultas WHERE paciente_id = ?',
);
console.log(consultasDoPaciente.all(42));

// Conferência honesta: o plano mostra o índice em uso
const plano = db.prepare(
  'EXPLAIN QUERY PLAN SELECT * FROM consultas WHERE paciente_id = ?',
);
console.log(plano.all(42).map((linha) => linha.detail));
